"""Release 8.0.0: Online Resource 5 of the fifth UMUAI version (markdown), from results_r22 and the earlier result files.

Changes from release 7.0.0 (r21_supplement.py): three worlds with per-world intervals; share of first attempts made before the
prerequisites are mastered; recall of G100 against the true edges among KCs seen in the logs (and against all true edges);
t-based MDEs with corpus mean, mixed-model estimate and three intervals; chance-corrected agreement and restricted candidate
sets; MIRT simulator; closed loop with 24 tracers per world and intervals over training cells; partial Q-matrix perturbation;
other graph constructions. Cell text never contains '|', which shifted columns in Table S19.1 of release 7.0.0.
"""
import os, json, glob, numpy as np, pandas as pd
REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); R = f'{REPO}/results_r22'; R21 = f'{REPO}/results_r21'
J = lambda p: json.load(open(p))
f4 = lambda x: ('---' if x is None or (isinstance(x, float) and np.isnan(x)) else f'{x:+.4f}'.replace('-', '−'))
iv = lambda c: '---' if c is None else f'{f4(c[0])}, {f4(c[1])}'
NAME = dict(assist09='ASSISTments 2009', assist12='ASSISTments 2012', assist15='ASSISTments 2015', assist17='ASSISTments 2017', junyi='Junyi Academy',
            algebra05='Algebra 2005', eedi='Eedi', ednet='EdNet KT1', bridge06='Bridge to Alg. 2006', statics11='Statics 2011', dbe_kt22='DBE-KT22',
            sim_dbe='sim-DBE', sim_dbe_mix='sim-DBE-mix', sim_a09='sim-A09')
TL = {'uni_emb-empty': 'U − ∅', 'true_er_emb-uni_emb': 'ER(G*) − U', 'true_dp_emb-true_er_emb': 'DP(G*) − ER(G*)', 'true_emb-true_dp_emb': 'G* − DP(G*)',
      'true_emb-empty': 'G* − ∅', 'er_emb-uni_emb': 'ER(G) − U', 'dp_emb-er_emb': 'DP(G) − ER(G)', 'support_emb-dp_emb': 'G − DP(G)',
      'support_emb-empty': 'G − ∅', 'true_emb-support_emb': 'G* − G'}
WORLDS = ('sim_dbe', 'sim_dbe_mix', 'sim_a09')
clean = lambda x: str(x).replace('|', '/')


def table(df):
    cols = [clean(c) for c in df.columns]; L = ['| ' + ' | '.join(cols) + ' |', '|' + '|'.join(['---'] * len(cols)) + '|']
    L += ['| ' + ' | '.join(clean(x) for x in r) + ' |' for r in df.itertuples(index=False)]
    return '\n'.join(L)


def s17(L):
    PC = J(f'{R}/positive_control.json'); GR = J(f'{R21}/graphs.json'); SH = J(f'{R}/prereq_share.json')
    L += ['# S17 Simulated worlds and the positive control', '',
          'Learners are generated by `kt/src/r20_sim.py` (sim-DBE, sim-A09) and `kt/src/r22_sim.py` (sim-DBE-mix; world parameters and true graph copied from sim-DBE, each learner\'s curriculum position perturbed by Gaussian noise with standard deviation K/3, drawn from a separate random stream). The tracers are trained by `kt/src/r21_controls.py` under the update budget, graph in the embedding refinement. Terms on first attempts; mean over subsamples 0, 1, 2 (subsample 0 only at 100%); in parentheses units with a positive difference; interval: *t* over the three subsamples of the world (`kt/src/r22_analyse.py`). The worlds differ in kind, so the main text pools no interval over them; the pooled values are given at the end of this section for comparison with the first revision.', '']
    for i, w in enumerate(WORLDS):
        B = PC['by_world'].get(w, {}); rows = []
        for key, lab in TL.items():
            r = {'Term': lab}
            for f in ('5', '10', '25', '100'):
                v = B.get(f, {}).get(key); r[f'{f}%'] = '---' if v is None else f"{f4(v['mean'])} ({v['pos']}/{v['n']})"
                if f != '100': r[f'{f}% interval'] = '---' if v is None or v.get('ci') is None else iv(v['ci'])
            rows.append(r)
        L += [f'**Table S17.{i + 1}** {NAME[w]}: ladder on the true graph G* and on the log-built graph G, first attempts', '', table(pd.DataFrame(rows)), '']
        rows = []
        for f in ('5', '10', '25', '100'):
            a = B.get(f, {}).get('auc', {})
            if a: rows.append({'Training learners': f'{f}%', **{c: f'{a[c]:.4f}' for c in ('empty', 'uni_emb', 'true_er_emb', 'true_dp_emb', 'true_emb', 'er_emb', 'dp_emb', 'support_emb') if c in a}})
        if rows: L += [f'First-attempt AUC by condition ({NAME[w]}):', '', table(pd.DataFrame(rows).fillna('---')), '']
    rows = [{'World': NAME[w], 'First attempts before all true prerequisites mastered': f"{SH[w]['share_all']:.3f}",
             'Correct if prerequisites unmet': f"{SH[w]['correct_if_unmet']:.3f}", 'Correct if met': f"{SH[w]['correct_if_met']:.3f}"} for w in WORLDS if w in SH]
    L += ['**Table S17.4** Signal available to the positive control: first attempts in the generated logs (all learners) made before every true prerequisite of the KC was mastered (`kt/src/r22_sim.py`, function `share`)', '', table(pd.DataFrame(rows)), '']
    rows = []
    for w, res in GR['sim_recovery'].items():
        d = pd.DataFrame(res).groupby('frac').mean(numeric_only=True)
        for f, r in d.iterrows():
            rows.append({'World': NAME[w], 'Training learners': f'{int(f * 100)}%', 'Edges of G': f"{r.edges:.0f}", 'Edges of G* among KCs in the logs': f"{r.true_edges:.0f}",
                         'Recall of G*': f'{r.recall:.2f}', 'Precision': f'{r.precision:.2f}', 'Reversed edges of G*': f'{r.reversed:.2f}'})
    L += ['**Table S17.5** Recovery of the true graph by the support graph of Eq. (2) built from the simulated logs (mean over subsamples). sim-A09 has 557 true edges on its 111 KCs; 438 of them join KCs that occur in the simulated logs, and recall here is computed against those 438. Against all 557 true edges the recall of G~100~ is 0.33 (the value printed in the header of Table S21.2 of the previous version, which used the other denominator). sim-DBE-mix shares the true graph of sim-DBE.', '', table(pd.DataFrame(rows)), '']
    P = PC.get('pooled', {}); rows = []
    for f in ('5', '10', '25'):
        v = P.get(f, {}).get('true_emb-true_dp_emb')
        if v: rows.append({'Training learners': f'{f}%', 'G* − DP(G*), sim-DBE and sim-A09 pooled': f"{f4(v['mean'])} ({v['pos']}/{v['n']})"})
    if rows: L += ['Pooled over sim-DBE and sim-A09 (six units), for comparison with Table 2 of the previous version:', '', table(pd.DataFrame(rows)), '']


def s18(L):
    GR = J(f'{R21}/graphs.json'); rows = []
    for c, rs in GR['s_sensitivity'].items():
        d = pd.DataFrame(rs).groupby('s').mean(numeric_only=True)
        rows.append({'Corpus': NAME[c], **{f'Edges s={s}': f'{d.loc[s, "edges"]:.0f}' for s in (5, 10, 20)},
                     **{f'Precision s={s}': f'{d.loc[s, "precision"]:.2f}' for s in (5, 10, 20)}, **{f'Recall s={s}': f'{d.loc[s, "recall"]:.2f}' for s in (5, 10, 20)}})
    L += ['# S18 Sensitivity of the support graph to the threshold s of Eq. (2)', '',
          'At 10% of the training learners, mean over five subsamples; precision and recall against G~100~ built with s = 10 (`kt/src/r21_graphs.py`). A pair (a, b) is an edge exactly when T(a→b) + T(b→a) ≥ s and T(a→b) > T(b→a); the script checks this equivalence on every graph.', '',
          '**Table S18.1** Edges and agreement with G~100~ by s', '', table(pd.DataFrame(rows)), '']


def s19(L):
    ST = J(f'{R}/stats_r22.json'); rows = []
    for k, v in ST['ladder'].items():
        if 'mean' not in v: continue
        rows.append({'Term': k.replace('_', ' '), 'Mean (>0)': f"{f4(v['mean'])} ({v['pos']})", 'Mixed': f4(v.get('est')),
                     'Mixed 95%': iv([v['lo'], v['hi']]) if 'lo' in v else '---', 't 95%': iv(v.get('t')), 'Bootstrap 95%': iv(v.get('boot')),
                     'MDE': f"{v['mde_t']:.4f}" if v.get('mde_t') is not None else '---'})
    L += ['# S19 Estimates, intervals and power of every comparison', '',
          'First attempts at a KC, 10% of the training learners, update budget (`kt/src/r22_stats.py`). Corpus mean: mean over corpora of the subsample means. Mixed: random intercept per corpus. *t*: interval over corpus means with df = corpora − 1. Bootstrap: 2,000 resamples of corpora, then of units within corpora. MDE = (*t*~0.975,df~ + *t*~0.80,df~) SE with the standard error of the mixed model and df = corpora − 1; with ten corpora the factor is 3.15 instead of 2.80 for normal quantiles. Terms prefixed other/ are the DKT conditional-influence graph (DKT) and the co-performance graph (corr) of release 4.1.0; DP(DKT) is the degree-preserving rewiring of DKT.', '',
          '**Table S19.1** Every exploratory term (mean over corpora with, in parentheses, the number of corpora with a positive difference; MDE: *t*-based, 80% power)', '', table(pd.DataFrame(rows)), '']
    for lab, k in (('both entry points', 'both: support - empty | test_auc_first'), ('embedding refinement (E) only', 'E: support_emb - empty | test_auc_first'),
                   ('edge term, (E)', 'E: support_emb - dp_emb | test_auc_first')):
        v = ST[k]
        L += [f"*{lab}*: corpus mean {f4(v['mean'])} ({v['pos']} of {v['corpora']} corpora, {v['units']} units); mixed {f4(v['mixed']['est'])} [{iv([v['mixed']['lo'], v['mixed']['hi']])}]; *t* [{iv(v['t'])}]; bootstrap [{iv(v['boot'])}]; MDE {v['mde_t']:.4f}.", '']
    rows = [{'Corpus': NAME[c], 'G − ∅, (E), first attempts': f4(x)} for c, x in ST['E: support_emb - empty | test_auc_first']['per_corpus'].items()]
    L += ['**Table S19.2** Per-corpus values behind Fig. 5', '', table(pd.DataFrame(rows)), '']
    SM = J(f'{R21}/stats_more.json'); e = SM['ensembles']
    rows = [{'Corpus': NAME[r['data']], 'Subsample': r['sub'], 'Graph gain, single seeds': f4(r['single_gain']), 'Graph gain, ensembles': f4(r['ens_gain']),
             'Ensemble − single, control': f4(r['ens_control_minus_single']), 'Ensemble − single, graph': f4(r['ens_graph_minus_single'])} for r in e['per_unit']]
    L += [f'**Table S19.3** Seed ensembles on first-attempt AUC at 10% (three seeds per model). {len(rows)} units on {len(set(r["data"] for r in e["per_unit"]))} corpora have prediction files for all six runs; one EdNet unit of the 14 three-seed units lacks them.', '', table(pd.DataFrame(rows)), '']


def s20(L):
    D = J(f'{R}/decisions_r22.json'); DM = J(f'{R21}/decisions_more.json')['per_corpus']; rows = []
    for c, d in D.items():
        for sname, s in d['sets'].items():
            rows.append({'Corpus': NAME[c], 'Candidates': {'all': 'all unattempted', 'window': 'curriculum window', 'unit': 'current and next unit'}[sname],
                         'Mean size': f"{s['mean_candidates']:.1f}", 'Chance': f"{s['chance']:.3f}", 'Seeds agree': f"{s['seeds']:.3f}", 'κ seeds': f"{s['kappa_seeds']:.3f}",
                         'Crossed agree': f"{s['crossed']:.3f}", 'κ crossed': f"{s['kappa_crossed']:.3f}", 'Decision points': s['points']})
    L += ['# S20 Further decision analyses on the real corpora', '',
          '`kt/src/r22_decisions.py`; 25% of the training learners, subsample 0, seeds 0, 100, 200; target rule (τ = 0.65); candidate scores of release 5.0.0. κ = (agreement − chance)/(1 − chance), with chance the mean of 1/|candidates| over decision points. Curriculum window: the ten KCs that follow the learner\'s current KC in curriculum order. Unit: KCs of the current and the next curriculum unit, for corpora with units, decision points with at least two candidates.', '',
          '**Table S20.1** Agreement by corpus and candidate set', '', table(pd.DataFrame(rows)), '']
    tau = []
    for c, d in DM.items():
        for tv, v in d['tau'].items(): tau.append(dict(tau=float(tv), **v))
    t = pd.DataFrame(tau).groupby('tau').mean(numeric_only=True).reset_index()
    t = pd.DataFrame({'τ': t.tau, 'Seeds agree': t.control_seeds.map('{:.3f}'.format), 'Crossed agree': t.graph_control_crossed.map('{:.3f}'.format),
                      'Graph regret change, Rasch': t.regret_change_rasch.map(f4), 'Graph regret change, global-practice': t.regret_change_pfa.map(f4),
                      'Seed SD of regret, Rasch': t.seed_sd_rasch.map('{:.4f}'.format), 'Seed SD of regret, global-practice': t.seed_sd_pfa.map('{:.4f}'.format)})
    L += ['**Table S20.2** Sensitivity to the target τ, all unattempted candidates (mean over ten corpora; release 7.0.0)', '', table(t), '']
    rows = []
    for c, d in DM.items():
        for frac, v in d['kc_rate_rule'].items():
            for sl, x in v.items():
                ne = pd.DataFrame(x['neural']).T
                rows.append({'Corpus': NAME[c], 'Size': f'{frac}%', 'Simulator': {'pfa': 'global-practice'}.get(sl, sl), 'KC rate, target': f"{x['kc_rate']['target']:.4f}", 'Tracers, target': f"{ne['target'].mean():.4f}",
                             'KC rate, easiest': f"{x['kc_rate']['easiest']:.4f}", 'Tracers, easiest': f"{ne['easiest'].mean():.4f}"})
        m = d_m = D[c]['mirt_regret']
        for frac in ('5', '25'):
            ne = pd.DataFrame({k: v for k, v in m['models'].items() if k.split('|')[0] == frac}).T
            if not len(ne) or frac not in m['kc_rate']: continue
            rows.append({'Corpus': NAME[c], 'Size': f'{frac}%', 'Simulator': 'MIRT', 'KC rate, target': f"{m['kc_rate'][frac]['target']:.4f}", 'Tracers, target': f"{ne['target'].mean():.4f}",
                         'KC rate, easiest': f"{m['kc_rate'][frac]['easiest']:.4f}", 'Tracers, easiest': f"{ne['easiest'].mean():.4f}"})
    L += ['**Table S20.3** Regret of the KC-rate rule and of the tracers by corpus and simulator (Rasch and global-practice: release 7.0.0; MIRT: release 8.0.0). The global-practice simulator was labelled "pfa" in the previous version; its success and failure counts run over all KCs, so it has no KC-specific learning.', '', table(pd.DataFrame(rows).sort_values(['Corpus', 'Simulator', 'Size'])), '']
    rows = [{'Corpus': NAME[c], 'Learner-level rank correlation': f"{D[c]['mirt_learner_rank_corr']:.3f}", 'Mean log-likelihood': f"{D[c]['mirt_fit']['mean_loglik']:.4f}", 'Test learners': D[c]['mirt_fit']['N']} for c in D]
    L += ['**Table S20.4** Fit of the two-dimensional IRT simulator (fitted to the test learners\' whole logs; L2 penalty 1, L-BFGS)', '', table(pd.DataFrame(rows)), '']


def s21(L):
    from r22_simdec import effect
    L += ['# S21 Decisions in the simulated worlds', '',
          '`kt/src/r22_simdec.py`; 500 learners, 20 warm-up steps, 40 adaptive steps; outcomes are means over learners. Net mastered: KCs mastered after the adaptive steps minus before them. Blocked: share of choices with an unmastered true prerequisite. Frustration: share of answers that are the third or later failure in a row. Regret: absolute difference between the true success of the chosen KC and τ = 0.65. Oracle: KC with true success closest to τ; learning oracle: unmastered KC with the highest true probability of being learned at this step. Effects: *t* intervals over training cells (subsample × size).', '']
    for i, w in enumerate(WORLDS):
        p = f'{R}/decisions_sim_{w}.json'
        if not os.path.exists(p): continue
        S = J(p); rows = []
        for q, v in S['reference'].items():
            rows.append({'Tracer': '---', 'Policy': q, 'Net mastered': f"{v['gain']:.2f}", 'Blocked': '---', 'Frustration': f"{v['frustration']:.3f}", 'Regret': f"{v['regret']:.3f}"})
        for g, v in S['kcrate'].items():
            rows.append({'Tracer': '---', 'Policy': f'KC rate, gate {g}', 'Net mastered': f"{v['gain']:.2f}", 'Blocked': f"{v['blocked_by_true_state']:.3f}", 'Frustration': f"{v['frustration']:.3f}", 'Regret': f"{v['regret']:.3f}"})
        for tag, rec in S['models'].items():
            for k, v in rec.items():
                if not isinstance(v, dict) or '|' not in k: continue
                rows.append({'Tracer': f"{rec['cond']}, {int(rec['frac'] * 100)}%, subsample {rec['sub']}", 'Policy': k.replace('|', ', gate '), 'Net mastered': f"{v['gain']:.2f}",
                             'Blocked': f"{v['blocked_by_true_state']:.3f}", 'Frustration': f"{v['frustration']:.3f}", 'Regret': f"{v['regret']:.3f}"})
        L += [f'**Table S21.{i + 1}** {NAME[w]}: {S["edges_true"]} true edges; G~100~ of the logs {S["edges_g100"]} edges, recall {S["g100_vs_true"]["recall"]:.2f} against all true edges, precision {S["g100_vs_true"]["precision"]:.2f}. Mastered after the warm-up {S["mastered_after_warmup"]:.2f}; expected net change with no practice over 40 steps −{S["expected_forgotten_without_practice"]:.2f}.', '', table(pd.DataFrame(rows)), '']
        er = []
        for lab, a, b, inp in (('Gate G* − no gate, target', 'target|true', 'target|none', None), ('Gate DP(G*) − no gate, target', 'target|dp', 'target|none', None),
                               ('Gate G100 − no gate, target', 'target|g100', 'target|none', None), ('Gate G* − no gate, frontier', 'frontier|true', 'frontier|none', None),
                               ('Tracer input G* − empty, target, no gate', 'target|none', None, ('true_emb', 'empty')), ('Tracer input DP(G*) − empty, target, no gate', 'target|none', None, ('true_dp_emb', 'empty')),
                               ('Tracer input G − empty, target, no gate', 'target|none', None, ('support_emb', 'empty'))):
            d = effect(S, a, b, inp=inp) if inp else effect(S, a, b)
            er.append({'Effect on net mastered': lab, 'Mean': f"{d['mean']:+.2f}".replace('-', '−'), '95% interval': f"{d['lo']:+.2f}, {d['hi']:+.2f}".replace('-', '−'), 'Positive': f"{d['pos']}/{d['n']}"})
        L += [f'**Table S21.{i + 1}b** {NAME[w]}: effects with intervals over training cells', '', table(pd.DataFrame(er)), '']


def s22(L):
    XR = J(f'{R21}/xes_routes.json'); rows = []
    for k, v in XR.items():
        if isinstance(v, dict) and 'values' in v and ':all' not in k:
            rows.append({'Comparison': k, 'Mean': f4(v['mean']), 'Positive': f"{v['pos']}/{v['n']}", 'By subsample': ', '.join(f4(x) for x in v['values'])})
    L += ['# S22 Authored structures, the item-level probe and the Q-matrix perturbations', '',
          f"XES3G5M KC routes (`kt/data/xes3g5m_route.json`, from `metadata/questions.json` and `kc_routes_map.json` of the original release): {XR.get('route_edges', 0):.0f} edges at 10% (mean over subsamples). First attempts, update budget, embedding refinement; empty and support graph from release 3.11.0." +
          (f" A rerun of the archived empty-graph control on subsample 0 of the rebuilt corpus differs from the archived first-attempt AUC by {XR['repro_empty_s0']['abs_diff']:.1e}." if 'repro_empty_s0' in XR else ''), '',
          '**Table S22.1** XES3G5M routes', '', table(pd.DataFrame(rows)), '']
    A20 = J(f'{REPO}/results_r20/analysis.json'); rows = []
    for k in ('q_qm-q_rqm', 'q_qm-q_id', 'q_qm_g-q_qm_dp', 'q_diff-q_kc'):
        v = A20['item'][k]
        for col in ('test_auc_first', 'test_auc_first_item'):
            rows.append({'Comparison': k, 'Outcome': col, 'Mean': f4(v[col]['mean']), 'Positive': f"{v[col]['pos']}/{v[col]['n']}",
                         **{NAME.get(c, c): f4(x) for c, x in v[col]['per_corpus'].items()}})
    L += ['**Table S22.2** Item-level probe (release 6.0.0 runs, `kt/runs_r20`): per corpus, mean over subsamples', '', table(pd.DataFrame(rows).fillna('---')), '']
    p = f'{R}/q_partial.json'
    if os.path.exists(p):
        Q = J(p); rows = []
        for k, v in Q.items():
            if not isinstance(v, dict) or 'mean' not in v: continue
            rows.append({'Comparison and outcome': k.replace('|', ', '), 'Mean': f4(v['mean']), 'Positive': f"{v['pos']}/{v['n']}", 't 95%': iv(v.get('ci')),
                         **{NAME.get(c, c): f4(x) for c, x in v.get('per_corpus', {}).items()}})
        L += ['**Table S22.3** Partial perturbation of the Q-matrix (`kt/src/r20_controls.py`, conditions q_pqm10 and q_pqm20; release 8.0.0): the KCs of a random 10% or 20% of the questions are permuted among those questions, so every KC keeps its number of questions; one or two subsamples per corpus (ten units on seven corpora, matched to the q_qm and q_rqm runs of release 6.0.0), 10% of the training learners, update budget; interval: *t* over corpus means' +
              (f". A rerun of the archived q_qm condition on Statics 2011 differs from the archived first-attempt AUC by {Q['repro']['abs_diff']:.1e}" if 'repro' in Q else '') + '.', '', table(pd.DataFrame(rows).fillna('---')), '']


def s23(L):
    L += ['# S23 Runs of this revision', '', 'The run lists are `kt/results_r21/run_list_r21.csv` (release 7.0.0) and `kt/results_r22/run_list_r22.csv` (release 8.0.0): world or corpus, training size, subsample, seed, condition, number of updates, test AUC, test AUC on first attempts and training time.', '']


def run_list():
    rows = []
    for d in ('runs_r22_sim', 'runs_r22'):
        for f in sorted(glob.glob(f'{REPO}/{d}/*__steps.json')):
            j = J(f); rows.append(dict(dir=d, data=j['data'], frac=j['frac'], sub=j['sub'], rep=j.get('rep', 0), seed=j['seed'], cond=j['cond'],
                                       steps=j['steps'], test_auc=j['test_auc'], test_auc_first=j['test_auc_first'], secs=round(j.get('secs_total', 0))))
    pd.DataFrame(rows).to_csv(f'{R}/run_list_r22.csv', index=False); print('runs', len(rows))


def main():
    L = ['---', 'title: "Online Resource 5"', '---', '',
         '**Do log-built concept graphs help KC-level learner models? Entry-point null graphs, a positive control and decision-level tests**', '',
         'Hai Bang Truong, Saigon International University. User Modeling and User-Adapted Interaction.', '',
         'Sections S17 to S23, added in the first and second revisions. Every value is produced by release 8.0.0 of the accompanying code (`kt/src/r21_*.py`, `kt/src/r22_*.py`) from the run files of `kt/runs_r21_sim`, `kt/runs_r21`, `kt/runs_r22_sim`, `kt/runs_r22` and the earlier releases; the result files are `kt/results_r21/*.json` and `kt/results_r22/*.json`.', '']
    for f in (s17, s18, s19, s20, s21, s22, s23): f(L)
    open(f'{R}/online_resource_5.md', 'w').write('\n'.join(L)); print('written', len(L))


if __name__ == '__main__':
    import sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    main(); run_list()
